package com.whalerein.android.corebridge

/**
 * Build provenance shared by the app and diagnostics.
 *
 * `CORE_REVISION` is generated by Gradle with the same source marker passed to
 * the Rust build, so the app can report the exact Core revision it links.
 */
object CoreProvenance {
    val coreRevision: String = BuildConfig.CORE_REVISION
    val coreVersion: String = BuildConfig.CORE_VERSION
    val appVersion: String = BuildConfig.APP_VERSION
    val androidRedirectUri: String = BuildConfig.ANDROID_REDIRECT_URI
}
